Arguments: {"title":"Find time period selector on Steam Deck top played page","code":"const tabId = 248688717;

const controls = await browserjs(tabId, () => {
  const elements = Array.from(document.querySelectorAll('*'));
  const matches = elements.filter(el => {
    const text = el.textContent?.trim() || '';
    return (text.includes('past week') || text.includes('past year') || text.includes('past month')) && el.children.length <= 2;
  });
  return matches.map(el => ({
    tagName: el.tagName,
    className: el.className,
    id: el.id,
    text: el.textContent?.trim(),
    html: el.outerHTML
  }));
});

console.log("Time controls:", controls);
